import { trainLookup, lookupDelivery } from './packages/attention-is-all-you-need/workflow.mjs';

const model = trainLookup({ epochs: 800, seed: 42 });
const context = [
  { person: 'Mira', day: 'Thursday' },
  { person: 'Noah', day: 'Friday' }
];
console.log(lookupDelivery(model, context, 'Mira'));
// answer: Thursday; also returns scores, weights and values.

